extends CharacterBody2D

@onready var nav_agent: NavigationAgent2D = $NavigationAgent2D

@export var movement_speed: float = 200.0

var reached: bool = false

func _ready() -> void:
    nav_agent.target_reached.connect(_on_target_reached)

func _on_target_reached() -> void:
    reached = true

func set_destination(dest: Vector2) -> void:
    nav_agent.target_position = dest
    reached = false

func _physics_process(_delta: float) -> void:
    # Only drive once the navigation map has sync'd (map iteration id > 0).
    if NavigationServer2D.map_get_iteration_id(get_world_2d().navigation_map) == 0:
        return

    if nav_agent.is_navigation_finished():
        velocity = Vector2.ZERO
        move_and_slide()
        return

    var next_pos := nav_agent.get_next_path_position()
    var direction := (next_pos - global_position).normalized()
    velocity = direction * movement_speed
    move_and_slide()

extends Node2D

@onready var region: NavigationRegion2D = $Region
@onready var obstacles_node: Node2D = $Obstacles
@onready var agent: CharacterBody2D = $Agent
@onready var goal: Marker2D = $Goal

func _ready() -> void:
    # Initialize an empty navigation region.
    var nav_poly := NavigationPolygon.new()
    nav_poly.parsed_geometry_type = NavigationPolygon.PARSED_GEOMETRY_BOTH_STATIC
    nav_poly.source_geometry_mode = NavigationPolygon.SOURCE_GEOMETRY_ROOT_NODE_CHILDREN_WITH_NESTED_CHILDREN
    region.navigation_polygon = nav_poly

func rebake_navigation() -> void:
    var source_geometry := NavigationMeshSourceGeometryData2D.new()

    # Walkable area outline: rectangle (0, 0) to (800, 600).
    var walk_outline := PackedVector2Array([
        Vector2(0, 0),
        Vector2(800, 0),
        Vector2(800, 600),
        Vector2(0, 600)
    ])
    source_geometry.add_traversable_outline(walk_outline)

    # Obstacles carve out paths.
    for obstacle in obstacles_node.get_children():
        if not (obstacle is NavigationObstacle2D):
            continue
        var obstacle_vertices := obstacle.vertices
        if obstacle_vertices.size() < 3:
            continue
        # World-space outline.
        var world_outline := PackedVector2Array()
        var obstacle_pos := obstacle.global_position
        for vertex in obstacle_vertices:
            world_outline.append(obstacle_pos + vertex)
        source_geometry.add_obstruction_outline(world_outline)

    var bake_source_geometry_parsing_callback := func(_geometry: NavigationMeshSourceGeometryData2D): pass

    NavigationServer2D.bake_from_source_geometry_data(
        region.navigation_polygon,
        source_geometry,
        bake_source_geometry_parsing_callback
    )

func move_obstacle(name: String, new_pos: Vector2) -> void:
    var obstacle := obstacles_node.get_node_or_null(name)
    if obstacle:
        obstacle.global_position = new_pos
        rebake_navigation()

func start_navigation() -> void:
    rebake_navigation()
    agent.call("set_destination", goal.global_position)

