                if is_ear([poly[j] for j in indices], i): found=True; break
            if not found: raise Exception("non-simple or self-intersecting?")
    triangles.append([indices[0], indices[1], indices[2]])
    return poly, triangles

def merge_holes(outer, holes):
    poly = list(outer)
    holes = sorted(holes, key=lambda h: max(p[0] for p in h), reverse=True)
    for h in holes:
        k = 0
        for i in range(1, len(h)):
            if h[i][0] > h[k][0]: k = i
        pA, pB = h[k], h[(k-1)%len(h)]
        p1, p2 = (pA, pB) if pA[1] < pB[1] else (pB, pA)
        h_ccw = list(reversed(h)) if not is_ccw(h) else list(h)
        i1, i2 = -1, -1
        for i in range(len(h_ccw)):
