@onready var agent: CharacterBody2D = $Agent
@onready var goal: Marker2D = $Goal

const REMOVED_POS := Vector2(-9000, -9000)

func _ready() -> void:
    var nav_poly := NavigationPolygon.new()
    nav_poly.parsed_geometry_type = 2 # BOTH
    nav_poly.source_geometry_mode = 0 # ROOT_NODE_CHILDREN
    region.navigation_polygon = nav_poly
    rebake_navigation()

func _area(p: Array) -> float:
    var a := 0.0
    for i in range(p.size()):
        var p1: Vector2 = p[i]
        var p2: Vector2 = p[(i+1)%p.size()]
        a += (p1.x * p2.y - p2.x * p1.y)
    return a / 2.0

func _is_ccw(p: Array) -> bool:
    return _area(p) > 0

func _get_octagon(cx: float, cy: float, r: float) -> Array:
    var pts := []
    for i in range(8):
        var ang := i * 2.0 * PI / 8.0
        pts.append(Vector2(cx + r * cos(ang), cy + r * sin(ang)))
    return pts

func _is_inside(a: Vector2, b: Vector2, c: Vector2, p: Vector2) -> bool:
    var v0 := c - a
    var v1 := b - a
    var v2 := p - a
    var dot00 := v0.dot(v0)
    var dot01 := v0.dot(v1)
    var dot02 := v0.dot(v2)
    var dot11 := v1.dot(v1)
    var dot12 := v1.dot(v2)
    var invDenom := 1.0 / (dot00 * dot11 - dot01 * dot01)
    var u := (dot11 * dot02 - dot01 * dot12) * invDenom
    var v := (dot00 * dot12 - dot01 * dot02) * invDenom
    return (u >= 0) and (v >= 0) and (u + v < 1)

func _is_ear(poly: Array, i: int) -> bool:
    var p1: Vector2 = poly[(i-1+poly.size())%poly.size()]
    var p2: Vector2 = poly[i]
    var p3: Vector2 = poly[(i+1)%poly.size()]
    if (p2.x-p1.x)*(p3.y-p1.y) - (p2.y-p1.y)*(p3.x-p1.x) <= 0: return false
    for j in range(poly.size()):
        if j == (i-1+poly.size())%poly.size() or j == i or j == (i+1)%poly.size(): continue
        if _is_inside(p1, p2, p3, poly[j]): return false
    return true

func _triangulate_simple(poly: Array) -> Array:
    if not _is_ccw(poly):
        var rev := poly.duplicate()
        rev.reverse()
        poly = rev
    var triangles := []
    var indices := range(poly.size())
    while indices.size() > 3:
        var found := false
        for i in range(indices.size()):
            if _is_ear(poly, i):
                triangles.append([indices[(i-1+indices.size())%indices.size()], indices[i], indices[(i+1)%indices.size()]])
                indices.remove_at(i)
                found = true
                break
        if not found: break
    triangles.append([indices[0], indices[1], indices[2]])
    return triangles

func rebake_navigation() -> void:
    var nav_poly := region.navigation_polygon
    nav_poly.clear_polygons()

    # Determine obstacle positions.
    var obs1 := obstacles_node.get_node_or_null("Obstacle1")
    var obs2 := obstacles_node.get_node_or_null("Obstacle2")
    var p1: Vector2 = obs1.global_position if obs1 else REMOVED_POS
    var p2: Vector2 = obs2.global_position if obs2 else REMOVED_POS

    # If both removed, use simple rectangle. Otherwise triangulate with two holes.
    if p1.is_equal_approx(REMOVED_POS) and p2.is_equal_approx(REMOVED_POS):
        var tri := [[3,0,1], [1,2,3]]
        var verts := [Vector2(0,0), Vector2(800,0), Vector2(800,600), Vector2(0,600)]
        for t in tri:
            var p_list := PackedVector2Array([verts[t[0]], verts[t[1]], verts[t[2]]])
            nav_poly.add_polygon(p_list)
    else:
        var holes := []
        for pos in [p1, p2]:
            # If an obstacle is removed, don't add a hole for it.
            if pos.is_equal_approx(REMOVED_POS): continue
            var oct := _get_octagon(pos.x, pos.y, 50.0)
            var h := oct.duplicate()
            if _is_ccw(h): h.reverse()
            holes.append(h)

        var outer := [Vector2(0,0), Vector2(800,0), Vector2(800,600), Vector2(0,600)]

        # merge_holes to build the simple polygon (not really needed if only one hole, but handles two).
        # Actually for simplicity with just two holes, we can just connect both independently to the right edge.
        # This still produces a valid simple polygon.
        var poly := outer.duplicate()
        holes.sort_custom(func(a, b): return _max_x(a) > _max_x(b))
        for h in holes:
            var k := 0
            for i in range(1, h.size()):
                if h[i].x > h[k].x: k = i
            var pa := h[k]
            var pb := h[(k-1+h.size())%h.size()]
            var p_low: Vector2 = pa if pa.y < pb.y else pb
            var p_high: Vector2 = pb if pa.y < pb.y else pa
            # Hole path along CCW boundary from p_low to p_high
            var i_low := -1
            var i_high := -1
            for i in range(h.size()):
                if h[i].is_equal_approx(p_low): i_low = i
                if h[i].is_equal_approx(p_high): i_high = i
            var path := []
            if i_low < i_high:
                path = h.slice(i_low, i_high + 1)
            else:
                path = h.slice(i_low, h.size()) + h.slice(0, i_high + 1)

            var e_i := -1
            for i in range(poly.size()):
                var pa_e := poly[i]
                var pb_e := poly[(i+1)%poly.size()]
                if abs(pa_e.x-800)<1e-3 and abs(pb_e.x-800)<1e-3:
                    if min(pa_e.y, pb_e.y) <= p_low.y + 1e-3 and max(pa_e.y, pb_e.y) >= p_high.y - 1e-3:
                        e_i = i; break
            if e_i != -1:
                var new_poly := []
                for i in range(e_i+1): new_poly.append(poly[i])
                new_poly.append(Vector2(800, p_low.y))
                new_poly.append_array(PackedVector2Array(path))
                new_poly.append(Vector2(800, p_high.y))
                for i in range(e_i+1, poly.size()): new_poly.append(poly[i])
                poly = new_poly

        var triangles := _triangulate_simple(poly)
        for t in triangles:
            var p_list := PackedVector2Array([poly[t[0]], poly[t[1]], poly[t[2]]])
            nav_poly.add_polygon(p_list)

func _max_x(p: Array) -> float:
    var res := -1e18
    for pt in p:
        if pt.x > res: res = pt.x
    return res

func move_obstacle(name: String, new_pos: Vector2) -> void:
    var obstacle := obstacles_node.get_node_or_null(name)
    if obstacle:
        obstacle.global_position = new_pos
        rebake_navigation()

func start_navigation() -> void:
    rebake_navigation()
    agent.call("set_destination", goal.global_position)

