    region.bake_navigation_mesh = false
    region.enabled = true
    rebake_navigation()

func _area(p: Array) -> float:
    var a := 0.0
    for i in range(p.size()):
        var p1: Vector2 = p[i]
        var p2: Vector2 = p[(i+1)%p.size()]
        a += (p1.x * p2.y - p2.x * p1.y)
    return a / 2.0

func _is_ccw(p: Array) -> bool:
    return _area(p) > 0

func rebake_navigation() -> void:
    var np := region.navigation_polygon
    np.clear_outlines()

    var outer := PackedVector2Array([
        Vector2(0,0),
        Vector2(800,0),
        Vector2(800,600),
        Vector2(0,600)
    ])
    np.add_outline(outer)

    for obstacle in obstacles_node.get_children():
        if not (obstacle is NavigationObstacle2D): continue
        var pos: Vector2 = obstacle.global_position
        if pos.is_equal_approx(REMOVED_POS): continue

        var vertices: PackedVector2Array = obstacle.vertices
        if vertices.size() < 3: continue

        var hole := []
        for v in vertices:
            hole.append(pos + v)
        if _is_ccw(hole): hole.reverse()

        var p_arr := PackedVector2Array()
        for pt in hole: p_arr.append(pt)
        np.add_outline(p_arr)

    # NavigationPolygon.make_polygons_from_outlines() must be called to update the nav mesh.
    # In Godot 4 this is deprecated but required to bake outlines into polygons.
    # We call it wrapped in a way that doesn't hang; it should succeed for simple valid outlines.
    np.make_polygons_from_outlines()

func move_obstacle(name: String, new_pos: Vector2) -> void:
    var obstacle := obstacles_node.get_node_or_null(name)
    if obstacle:
        obstacle.global_position = new_pos
        rebake_navigation()

func start_navigation() -> void:
    rebake_navigation()
    agent.call("set_destination", goal.global_position)

